"name":"_hiredTalentId","type":"uint256"},{"internalType":"address","name":"_freelancer","type":"address"},{"internalType":"bytes","name":"_arbitratorExtraData","type":"bytes"}],"name":"startAndPayTalentDisputeByClient","outputs":[{"internalType":"uint256","name":"localDisputeId","type":"uint256"}],"stateMutability":"payable","type":"function"},{"inputs":[{"internalType":"uint256","name":"_talentId","type":"uint256"},{"internalType":"uint256","name":"_hiredTalentId","type":"uint256"},{"internalType":"address","name":"_client","type":"address"},{"internalType":"bytes","name":"_arbitratorExtraData","type":"bytes"}],"name":"startAndPayTalentDisputeByFreelancer","outputs":[{"internalType":"uint256","name":"localDisputeId","type":"uint256"}],"stateMutability":"payable","type":"function"},{"inputs":[{"internalType":"uint256","name":"_localDisputeId","type":"uint256"}],"name":"timeoutByInaction","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"uint256","name":"_localDisputeId","type":"uint256"},{"internalType":"address payable","name":"_beneficiary","type":"address"},{"internalType":"uint256","name":"_round","type":"uint256"}],"name":"withdrawFeesAndRewards","outputs":[],"stateMutability":"nonpayable","type":"function"}],"devdoc":{"details":"Pure internal ID architecture for arbitration Key Design Principle: - Contract ONLY uses internal dispute IDs (localDisputeId) for all logic - External IDs (talentId, gigId, etc.) are stored as metadata in the struct - Frontend tracks externalId → localDisputeId mapping via events - No on-chain mappings from external IDs to internal IDs","events":{"Dispute(address,uint256,uint256,uint256)":{"details":"To be emitted when a dispute is created to link the correct meta-evidence to the disputeID.","params":{"_arbitrator":"The arbitrator of the contract.","_disputeID":"ID of the dispute in the Arbitrator contract.","_evidenceGroupID":"Unique identifier of the evidence group that is linked to this dis